/**
* Convierte JWK → HEX (64 bytes XY)
* Detecta la curva de la JWK individual.
*/
export declare function jwkToHex(jwk: any): string;
/**
* Convierte HEX → JWK usando la curva informada en el método.
* @param hex  0x + 64 bytes (XY)
* @param ellipticType  0=NONE, 1=K1, 2=R1
*/
export declare function hexToJwk(hex: string, ellipticType: number): any;
